USE CATALOG IDENTIFIER(:catalog);

-- cohort_retention: TEMP tables -> CTEs. Redshift DATEDIFF(month) counts month
-- boundaries crossed: (y2*12 + m2) - (y1*12 + m1).
CREATE OR REPLACE TABLE gold.cohort_retention (
    cohort_month   DATE,
    month_offset   INT,
    cohort_size    BIGINT,
    active_buyers  BIGINT
) CLUSTER BY (cohort_month, month_offset);

INSERT INTO gold.cohort_retention
WITH cohorts AS (
    SELECT customer_id,
           CAST(date_trunc('MONTH', MIN(order_ts)) AS DATE) AS cohort_month
    FROM   silver.orders
    GROUP  BY customer_id
),
activity AS (
    SELECT c.cohort_month,
           (year(o.order_ts) * 12 + month(o.order_ts))
             - (year(c.cohort_month) * 12 + month(c.cohort_month)) AS month_offset,
           COUNT(DISTINCT c.customer_id)                           AS active_buyers
    FROM   silver.orders o
    JOIN   cohorts c ON c.customer_id = o.customer_id
    GROUP  BY 1, 2
),
sizes AS (
    SELECT cohort_month, COUNT(*) AS cohort_size
    FROM   cohorts
    GROUP  BY cohort_month
)
SELECT s.cohort_month,
       s.month_offset,
       sz.cohort_size,
       s.active_buyers
FROM   activity s
JOIN   sizes sz ON sz.cohort_month = s.cohort_month;
